function date(value:string|number|null|undefined,time=false){if(value===null||value===undefined)return '기록 없음';const d=new Date(value);return Number.isFinite(d.getTime())?new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'long',day:'numeric',...(time?{hour:'numeric',minute:'numeric'}:{})}).format(d):'기록 없음';}
function day(value:string,last=false){const at=Date.parse(value)+(last?-1:0);return Number.isFinite(at)?new Date(at+9*3600000).toISOString().slice(0,10):'';}
const originText=(origin:ServiceOrigin)=>origin==='PERSONAL'?'직접 작성 · 원문 미검수':origin==='DEMO'?'가상 예시 · 실제 상품 아님':'제공 자료 · 원문 검수';
