type Route={key:number;type:'DETAIL';origin:ServiceOrigin;id:string}|{key:number;type:'CHECK';step:1|2|3}|{key:number;type:'WALLET_DETAIL'|'WALLET_EDIT'|'CODE';id?:string;providerId?:string;thenPersonal?:boolean}|{key:number;type:'PROVIDERS';thenPersonal?:boolean}|{key:number;type:'PERSONAL';id?:string;draftId?:string;productId?:string;step:number}|{key:number;type:'SETTINGS'|'HELP'|'ABOUT'|'PRIVACY'|'PERMISSIONS'|'DATA'|'REPORTS'}|{key:number;type:'REPORT';entry?:BenefitEntry;replace?:ReportReceipt};
